/* Separate routes, shared existing controls and authorization. */
(() => {
 const el=id=>document.getElementById(id),main=document.querySelector('main');
 const names={home:'Home',devices:'Devices',security:'Security',activity:'Activity',settings:'Settings'};
 const route=location.pathname.slice(1)||'home',current=names[route]?route:'home';
 const views={};for(const [key,title] of Object.entries(names)){const page=document.createElement('div');page.className='companion-page';page.hidden=key!==current;page.innerHTML='<div class="companion-heading"><p class="v2-eyebrow">WINDOWS COMPANION</p><h1>'+title+'</h1></div>';main.append(page);views[key]=page}
 function move(node,parent){if(node)parent.append(node)}
 function card(parent,title,text){const node=document.createElement('section');node.className='companion-card';const h=document.createElement('h2');h.textContent=title;node.append(h);if(text){const p=document.createElement('p');p.textContent=text;node.append(p)}parent.append(node);return node}
 const welcome=document.querySelector('.v2-welcome');move(welcome,views.home);
 const quick=card(views.home,'Start here','Pair your phone, configure AI and review your laptop permissions.');
 for(const [path,title] of [['devices','Connect your phone'],['settings','Set up AI'],['security','Review permissions'],['activity','Connection and activity']]){const link=document.createElement('a');link.className='v2-button';link.href='/'+path;link.textContent=title;quick.append(link)}
 const notice=el('notice');move(notice,main);main.insertBefore(notice,main.firstChild);
 move(el('v2-account-pair'),views.devices);
 const legacy=el('v2-connect'),advanced=document.createElement('details');advanced.className='companion-card';advanced.innerHTML='<summary>Advanced: existing local/private connection</summary><p>This is the earlier connection mode. Account pairing above is the normal online setup. Use this only if you already run a private controller.</p>';move(legacy,advanced);views.devices.append(advanced);
 const form=el('setup'),oldSettings=form.closest('details');
 const permissions=card(views.security,'What your phone may do','These permissions apply to this laptop. Sensitive actions still need the existing approval checks.');
 for(const id of ['powerPermission','desktopInput','remoteVoice']){const input=el(id);input.setAttribute('form','setup');move(input.closest('label'),permissions)}
 const apply=document.createElement('button');apply.type='button';apply.textContent='Apply laptop permissions';permissions.append(apply);
 apply.onclick=()=>setupTaskFor(apply,async()=>{await call('/permissions',{confirmed:true,system_controls:el('powerPermission').checked,desktop_input:el('desktopInput').checked,remote_voice:el('remoteVoice').checked});return 'Permissions saved. Pairing kept.'});
 for(const id of ['savePowerPermission','saveVoicePermission'])el(id).hidden=true;
 const folder=card(views.settings,'Shared folder','Only this selected folder is shared with approved file actions. Stop PC access before changing it.');el('folder').setAttribute('form','setup');move(el('folder').closest('label'),folder);move(el('chooseFolder'),folder);
 const folderSave=document.createElement('button');folderSave.type='button';folderSave.textContent='Save shared folder';folder.append(folderSave);folderSave.onclick=()=>setupTaskFor(folderSave,async()=>{await call('/permissions',{confirmed:true,folder:el('folder').value});return 'Shared folder saved. Start account connection when ready.'});
 move(el('startup').closest('.row'),views.settings);
 move(el('checkUpdates').closest('details'),views.settings);
 const settingsAdvanced=document.createElement('details');settingsAdvanced.className='companion-card';settingsAdvanced.innerHTML='<summary>Advanced: local password and private-server settings</summary><p>The app password protects the older local/private controller. It is not your Google password or mobile app PIN, and is not needed for account pairing. Reset signs out local sessions. Preview tokens apply only to developer-protected preview deployments.</p>';move(oldSettings,settingsAdvanced);views.settings.append(settingsAdvanced);
 el('password').closest('label').insertAdjacentHTML('beforeend','<small>Local/private controller only. Leave unchanged when using account pairing.</small>');
 move(el('status'),views.activity);move(el('voiceConnection'),views.activity);move(el('openApp').closest('.row'),views.activity);move(el('pending'),views.activity);const logs=el('logs');move(logs.previousElementSibling,views.activity);move(logs,views.activity);
 const ai=card(views.settings,'AI connection on this laptop','Your paired phone uses this laptop’s configured AI provider. Keys stay encrypted on this Windows account. Manual controls do not require AI.');
 ai.id='companionAi';views.settings.insertBefore(ai,views.settings.children[1]||null);
 ai.innerHTML+='<form id="ownerAiForm"><label>AI provider<select id="ownerAiProvider"><option value="groq">Groq</option><option value="gemini">Gemini</option><option value="openrouter">OpenRouter</option></select></label><label>API key<input id="ownerAiKey" type="password" autocomplete="off" placeholder="Paste key; leave blank to keep this provider’s saved key"></label><button id="ownerAiModels" type="button">Load available models</button><label>Model<select id="ownerAiModel"><option value="">Load models first</option></select></label><label class="check"><input id="ownerAiConsent" type="checkbox" required>Save these AI settings encrypted on this laptop.</label><div class="v2-actions"><button id="ownerAiSave">Save &amp; activate AI</button><button id="ownerAiTest" type="button">Test selected AI</button></div></form><p id="ownerAiStatus" role="status">Checking saved AI settings…</p>';
 const aiData=()=>({provider:el('ownerAiProvider').value,key:el('ownerAiKey').value,model:el('ownerAiModel').value});
 let aiInspected=false;
 async function aiStatus(){const r=await call('/ai/status',{});if(r.error)throw Error(r.error);if(!aiInspected&&r.active){el('ownerAiProvider').value=r.active;const saved=r.providers.find(p=>p.provider===r.active);if(saved){el('ownerAiModel').replaceChildren(new Option(saved.model,saved.model));}aiInspected=true}el('ownerAiStatus').textContent=r.providers.length?'Saved: '+r.providers.map(p=>p.provider+' / '+p.model).join(', '):'No AI provider saved. Paste a key, load models, select one and save.'}
 el('ownerAiProvider').onchange=()=>{el('ownerAiKey').value='';el('ownerAiModel').replaceChildren(new Option('Load this provider’s models',''))};
 el('ownerAiModels').onclick=()=>setupTaskFor(el('ownerAiModels'),async()=>{const chosen=aiData();const r=await call('/ai/models',chosen);if(el('ownerAiProvider').value!==chosen.provider)throw Error('Provider changed. Load models for the newly selected provider.');el('ownerAiModel').replaceChildren(new Option('Select a model',''));for(const model of r.models)el('ownerAiModel').add(new Option(model,model));return 'Models loaded. Availability and charges depend on your provider account.'},el('ownerAiStatus'));
 el('ownerAiForm').onsubmit=e=>{e.preventDefault();setupTaskFor(el('ownerAiSave'),async()=>{await call('/ai/save',{...aiData(),confirmed:el('ownerAiConsent').checked});el('ownerAiKey').value='';await aiStatus();if(el('ownerAiProvider').value==='gemini')el('geminiSync').click();return el('ownerAiStatus').textContent},el('ownerAiStatus'))};
 el('ownerAiTest').onclick=()=>setupTaskFor(el('ownerAiTest'),async()=>{const r=await call('/ai/test',aiData());return r.message},el('ownerAiStatus'));
 aiStatus().catch(error=>{el('ownerAiStatus').textContent=error.message});
 el('ownerAiKey').addEventListener('change',()=>{if(el('ownerAiKey').value.trim())el('ownerAiModels').click()});
 const speech=card(views.settings,'Gemini voice for laptop and phone','Uses the same saved Gemini key. Save your Gemini AI key above first. Speech text goes to Gemini; internet, account access and provider quota are required. Urdu, Saraiki and accent quality need your own listening test.');
 ai.after(speech);
 speech.innerHTML+='<button id="geminiSync" type="button">Sync Gemini speech models &amp; voices</button><label>Speech model<select id="geminiSpeechModel"></select></label><label>Voice<select id="geminiSpeaker"></select></label><label>Speaking style<textarea id="geminiStyle" maxlength="400">Polite, warm, natural and clear. Speak at a comfortable conversational pace.</textarea></label><label class="check"><input id="geminiEnabled" type="checkbox">Use Gemini cloud voice</label><label class="check"><input id="geminiConsent" type="checkbox">Allow my reviewed speech/replies to be sent to Gemini using my key.</label><label>Test phrase — use your own language<textarea id="geminiSpeechSample" maxlength="350">Hello. I am SARAS. How can I help you?</textarea></label><div class="v2-actions"><button id="geminiSave" type="button">Save voice choice</button><button id="geminiTest" type="button">Generate voice test</button></div><p id="geminiVoiceStatus" role="status"></p><audio id="geminiTestAudio" controls hidden></audio>';
 let speechCatalog={},speechAudioUrl='';
 function renderVoices(){const selected=el('geminiSpeaker').value;el('geminiSpeaker').replaceChildren();for(const voice of speechCatalog.voices||[]){if(!el('geminiSpeechModel').value.startsWith('gemini-3.8')&&!voice.legacy_compatible)continue;el('geminiSpeaker').add(new Option(voice.name,voice.id))}if([...el('geminiSpeaker').options].some(v=>v.value===selected))el('geminiSpeaker').value=selected}
 function renderSpeech(data){speechCatalog=data;el('geminiSpeechModel').replaceChildren(new Option('Select a speech model',''));for(const model of data.models||[])el('geminiSpeechModel').add(new Option(model,model));if(data.model)el('geminiSpeechModel').value=data.model;renderVoices();if(data.voice)el('geminiSpeaker').value=data.voice;if(data.style)el('geminiStyle').value=data.style;el('geminiEnabled').checked=!!data.enabled;el('geminiConsent').checked=!!data.enabled}
 el('geminiSpeechModel').onchange=renderVoices;
 el('geminiSync').onclick=()=>setupTaskFor(el('geminiSync'),async()=>{const key=el('ownerAiProvider').value==='gemini'?el('ownerAiKey').value:'';const data=await call('/gemini-voice/sync',{key});const selectedModel=el('geminiSpeechModel').value;renderSpeech({...speechCatalog,...data,model:selectedModel});return data.message},el('geminiVoiceStatus'));
 el('geminiSave').onclick=()=>setupTaskFor(el('geminiSave'),async()=>{const data=await call('/gemini-voice/save',{enabled:el('geminiEnabled').checked,confirmed:el('geminiConsent').checked,model:el('geminiSpeechModel').value,voice:el('geminiSpeaker').value,style:el('geminiStyle').value});return data.message},el('geminiVoiceStatus'));
 el('geminiTest').onclick=()=>setupTaskFor(el('geminiTest'),async()=>{const data=await call('/gemini-voice/test',{text:el('geminiSpeechSample').value});if(speechAudioUrl)URL.revokeObjectURL(speechAudioUrl);speechAudioUrl=URL.createObjectURL(new Blob([Uint8Array.from(atob(data.audio),c=>c.charCodeAt(0))],{type:data.mime}));el('geminiTestAudio').src=speechAudioUrl;el('geminiTestAudio').hidden=false;return 'Speech generated. Press Play below and check the pronunciation.'},el('geminiVoiceStatus'));
 call('/gemini-voice/status',{}).then(data=>{renderSpeech(data);el('geminiVoiceStatus').textContent=data.key_available?'Saved Gemini key is available. Sync the speech catalog to choose a model and voice.':'Save a Gemini key and chat model in AI settings first; voice reuses that key.'}).catch(error=>{el('geminiVoiceStatus').textContent=error.message});

 for(const link of document.querySelectorAll('.v2-sidebar nav a')){const active=(link.pathname==='/dashboard'&&current==='home')||link.pathname==='/'+current;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')}
 document.querySelector('.v2-help').innerHTML='<a href="/guide">Every button explained</a>';
 document.title='SARAS Companion · '+names[current];
 async function setupTaskFor(button,work,status=notice){const text=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');button.classList.add('is-loading');button.textContent='Please wait…';status.textContent='Working…';status.dataset.state='loading';try{status.textContent=await work();status.dataset.state='success'}catch(error){status.textContent=error.message;status.dataset.state='error'}finally{button.textContent=text;button.disabled=false;button.removeAttribute('aria-busy');button.classList.remove('is-loading')}}
})();
